const out = path.join(root, 'blog');
fs.mkdirSync(out, { recursive: true });

const domain = 'https://www.pinturastuled.com';
const phone = '5218112303901';
const published = '2026-10-29';
const shareImage = `${domain}/imgs/imagen-compartirlink.jpg`;
const identityHead = `<meta name="theme-color" content="#06452F"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-status-bar-style" content="black-translucent"><link rel="icon" type="image/png" sizes="32x32" href="/imgs/favicon-cuadrado.png"><link rel="icon" type="image/png" sizes="16x16" href="/imgs/favicon-cuadrado-16x16.png"><link rel="icon" type="image/png" sizes="48x48" href="/imgs/favicon-cuadrado-48x48.png"><link rel="apple-touch-icon" sizes="180x180" href="/imgs/favicon-redondo-180x180.png"><link rel="manifest" href="/site.webmanifest">`;
const socialHead = (title, description, url, type = 'website') => `<link rel="canonical" href="${url}"><meta property="og:type" content="${type}"><meta property="og:site_name" content="TULED"><meta property="og:locale" content="es_MX"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:image" content="${shareImage}"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:type" content="image/jpeg"><meta property="og:url" content="${url}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${esc(title)}"><meta name="twitter:description" content="${esc(description)}"><meta name="twitter:image" content="${shareImage}">`;

const articles = [
  {id:1,slug:'piezas-metalicas-pintura-electrostatica',title:'¿Qué piezas metálicas se pueden pintar con pintura electrostática?',cat:'Aplicaciones',image:'articulo-1.webp',excerpt:'Gabinetes, rejillas, soportes, racks y otras piezas que pueden evaluarse para recubrimiento en polvo.',intro:'La pintura electrostática puede aplicarse a muchas piezas metálicas, pero la viabilidad no depende solamente de que el componente sea de metal. Material, dimensiones, geometría, contaminación superficial, áreas que deben permanecer libres y capacidad para soportar el ciclo térmico forman parte de la evaluación.',points:[['Condiciones básicas de una pieza candidata','La pieza debe permitir limpieza, colgado, conexión a tierra, aplicación uniforme y curado conforme a la ficha del recubrimiento. Insertos sensibles al calor, sellos, electrónica o ensambles pueden requerir desmontaje.'],['Gabinetes, carcasas y paneles','Envolventes, puertas, tapas y paneles son aplicaciones habituales. Deben identificarse roscas, superficies de contacto, perforaciones y zonas de ensamble que quizá necesiten enmascarado.'],['Rejillas y climatización','Rejillas, cubiertas y componentes HVAC combinan perforaciones, bordes y zonas profundas. La geometría influye en el acceso de la nube de polvo y en la forma de sujetar la pieza.'],['Soportes, bases y maquinaria','Escuadras, bases, soportes soldados y componentes de maquinaria pueden evaluarse siempre que se conozcan su material, condición superficial y requisitos de uso. Soldadura, grasa o rebabas deben revisarse.'],['Racks, perfiles y estructuras','Postes, travesaños, marcos y perfiles requieren planear el colgado, la manipulación y el transporte. En lotes, la repetibilidad dimensional ayuda a organizar el proceso.'],['Piezas que requieren revisión especial','Fundición contaminada, piezas usadas, ensambles cerrados, cavidades profundas o componentes de gran masa pueden necesitar pruebas o preparación adicional. No todas las piezas son aptas sin una evaluación previa.']],quote:'La pieza, su uso y su geometría determinan cómo debe prepararse y recubrirse.',cta:'Cotizar una pieza metálica',message:'Hola Tuled, leí el artículo sobre piezas metálicas y quiero evaluar una pieza para pintura electrostática.',related:[5,14,15,17,18]},
  {id:2,slug:'precio-pintura-electrostatica-monterrey',title:'¿Cuánto cuesta pintar una pieza con pintura electrostática en Monterrey?',cat:'Cotización',image:'articulo-2.webp',excerpt:'Los factores que influyen en una cotización: tamaño, material, preparación, color, cantidad y plazo.',intro:'No existe un precio único por pieza porque dos componentes del mismo tamaño pueden implicar trabajos distintos. Una cotización responsable considera la superficie real, el estado del metal, el colgado, el enmascarado, la formulación, el volumen y el plazo solicitado.',points:[['Dimensiones y superficie','Largo, ancho, alto y área a recubrir ayudan a estimar consumo y ocupación. También importa si la pieza puede manipularse con seguridad y acomodarse en el proceso.'],['Material y condición inicial','Acero, aluminio, fundición o una pieza previamente pintada no se preparan igual. Aceite, oxidación, soldadura, recubrimientos anteriores y residuos cambian el alcance.'],['Geometría y enmascarado','Cavidades, dobleces, perforaciones, roscas y superficies que no deben pintarse agregan operaciones. Una geometría sencilla puede ser más eficiente que otra del mismo tamaño.'],['Color y acabado','Color, brillo, textura y familia de recubrimiento deben definirse. Un color de corrida frecuente puede organizarse de manera distinta a un desarrollo o igualación especial.'],['Cantidad y repetibilidad','Una pieza individual y un lote se planean de forma diferente. Cantidades, entregas parciales, variaciones entre piezas y frecuencia del pedido ayudan a definir la logística.'],['Plazo y recepción','Los tiempos dependen de disponibilidad, preparación y programación. Tuled se encuentra en Apodaca y atiende solicitudes industriales de Monterrey y su área metropolitana.']],quote:'Una buena cotización describe la pieza, no solamente su tamaño.',cta:'Solicitar cotización en Monterrey',message:'Hola Tuled, vi el artículo sobre costos de pintura electrostática. Estoy en Monterrey y quiero solicitar una cotización; entiendo que sus instalaciones están en Apodaca.',related:[6,4,1]},
  {id:3,slug:'que-es-pintura-electrostatica',title:'¿Qué es la pintura electrostática? Usos, ventajas y limitaciones',cat:'Fundamentos',image:'articulo-3.webp',excerpt:'Una introducción clara al recubrimiento en polvo, su aplicación electrostática y el curado.',intro:'La pintura electrostática en polvo es un sistema de acabado seco. De manera general, el material combina resinas, pigmentos, agentes de curado y aditivos; se carga durante la aplicación, se deposita sobre una pieza conectada a tierra y después se transforma mediante calor en una película continua.',points:[['Cómo se deposita el polvo','La pistola proporciona carga a las partículas y la pieza aterrizada favorece su atracción. La conexión a tierra, la distancia, el flujo y la geometría influyen en la deposición.'],['Qué ocurre durante el curado','El polvo aplicado entra a un horno y, bajo las condiciones indicadas por su formulación, fluye y reacciona para formar el acabado. Temperatura de metal y tiempo son variables distintas del ajuste del aire del horno.'],['Usos industriales','Se utiliza en gabinetes, racks, estructuras, rejillas, soportes, perfiles, cubiertas y muchos componentes metálicos. La formulación se selecciona según sustrato, ambiente y desempeño esperado.'],['Ventajas posibles','Puede ofrecer uniformidad, variedad de color y textura, y un proceso sin el solvente portador típico de numerosos sistemas líquidos. La recuperación de sobrepulverización depende del sistema y del control de contaminación.'],['Limitaciones','La pieza debe tolerar el ciclo térmico y permitir acceso, colgado y aterrizado. Los cambios de color, retoques, cavidades y sustratos sensibles requieren consideraciones específicas.'],['Cómo elegir proveedor','Conviene revisar experiencia, capacidad dimensional, preparación, trazabilidad, inspecciones y claridad para confirmar especificaciones. Ningún acabado sustituye una definición técnica del proyecto.']],quote:'No todas las piezas ni todos los sistemas de pintura requieren el mismo tratamiento.',cta:'Consultar un proyecto',message:'Hola Tuled, leí su introducción a la pintura electrostática y quiero saber si este proceso es adecuado para mis piezas.',related:[7,8,9]},
  {id:4,slug:'servicio-express-pintura-electrostatica',title:'Servicio Express de pintura electrostática: ¿cuándo es posible entregar en menos de 24 horas?',cat:'Cotización',image:'articulo-4.webp',excerpt:'Qué información y condiciones permiten evaluar una atención prioritaria en menos de 24 horas.',intro:'El Servicio Express es una modalidad de evaluación prioritaria para necesidades urgentes. “Menos de 24 horas” no es una promesa automática: depende de disponibilidad, tipo y cantidad de piezas, preparación requerida, color, capacidad de proceso y confirmación expresa de Tuled.',points:[['Cuándo puede ser útil','Puede apoyar ante reposiciones, prototipos, ajustes de producción o componentes que detienen una operación. La urgencia debe explicarse junto con la fecha y hora realmente necesarias.'],['Piezas y volumen','Piezas manejables, cantidades limitadas y geometrías conocidas suelen ser más fáciles de evaluar. Volúmenes grandes o componentes complejos pueden requerir otra programación.'],['Preparación previa','Grasa, oxidación, pintura anterior o contaminación pueden extender el proceso. Fotografías claras permiten anticipar parte de esta revisión, pero la recepción física confirma el estado.'],['Disponibilidad de color','El color, brillo y formulación deben estar disponibles y ser compatibles con el uso. Un color especial puede requerir abastecimiento o validación adicional.'],['Aplicación, curado y enfriamiento','Aun en un servicio urgente no deben omitirse las etapas necesarias. La pieza necesita aplicación, ciclo de curado, enfriamiento y revisión antes de manipularse.'],['Cómo solicitarlo','Envía fotos, medidas, material, cantidad, color, condición de la superficie y hora límite. La aceptación del plazo existe únicamente después de la confirmación de Tuled.']],quote:'La rapidez comienza con información completa y disponibilidad confirmada.',cta:'Consultar disponibilidad Express',message:'Hola Tuled, vi su artículo sobre Servicio Express y quiero consultar disponibilidad para unas piezas metálicas.',related:[6,2,7]},
  {id:5,slug:'piezas-aire-acondicionado-pintura-electrostatica',title:'¿Qué piezas de aire acondicionado pueden recibir pintura electrostática?',cat:'Aplicaciones',image:'articulo-5.webp',excerpt:'Carcasas, rejillas, soportes, paneles y envolventes metálicas para equipos de climatización.',intro:'Los equipos de climatización incluyen múltiples componentes metálicos que pueden evaluarse para pintura en polvo. La selección no depende solo de la apariencia: material, ambiente interior o exterior, ventilación, perforaciones, ensamble y temperatura de proceso deben considerarse.',points:[['Carcasas y cubiertas','Las envolventes exteriores pueden requerir color uniforme, control de apariencia y protección acorde al ambiente. Deben revisarse uniones, bordes y superficies de contacto.'],['Rejillas y paneles','Perforaciones y lamas crean zonas de acceso limitado. El diseño del colgado y la orientación ayudan a trabajar ambas caras y mantener libres los puntos definidos.'],['Soportes y bases','Bases, escuadras y marcos soldados pueden procesarse por lote. Soldadura, rebabas, aceite de fabricación y áreas de montaje deben comunicarse.'],['Interior y exterior','La exposición cambia la selección de formulación. Para exterior deben revisarse radiación solar, humedad y requisitos del cliente mediante la ficha técnica aplicable.'],['Preparación de superficie','Acero y aluminio necesitan rutas compatibles con su sustrato. Una superficie limpia y preparada favorece la adherencia; una pieza usada puede requerir evaluación adicional.'],['Información para cotizar','Comparte plano o fotos, medidas, material, cantidad, color, acabado, exposición y zonas que no se pintan. Indica si la pieza llega armada o desarmada.']],quote:'Una rejilla y una cubierta pueden pertenecer al mismo equipo, pero no presentan la misma geometría.',cta:'Cotizar componentes de climatización',message:'Hola Tuled, vi el artículo sobre piezas de aire acondicionado y deseo cotizar componentes de climatización.',related:[13,18,1]},
  {id:6,slug:'como-cotizar-pintura-electrostatica',title:'¿Cómo solicitar una cotización de pintura electrostática para piezas metálicas?',cat:'Cotización',image:'articulo-6.webp',excerpt:'Una lista práctica para reunir fotos, medidas, material, cantidad, color, acabado y fecha.',intro:'Una solicitud completa reduce preguntas, ayuda a detectar restricciones y permite preparar una propuesta más útil. No necesitas dominar el proceso: basta con compartir datos verificables y señalar lo que todavía está por definirse.',points:[['Fotografías útiles','Incluye vista completa, acercamientos de soldaduras, oxidación, roscas y zonas críticas. Agrega una referencia de escala sin ocultar la pieza.'],['Dimensiones y material','Indica largo, ancho, alto, peso aproximado y metal cuando se conozca. Si hay distintos modelos, separa cantidades y medidas.'],['Cantidad y frecuencia','Aclara si es una pieza, un lote único o una necesidad recurrente. La cadencia de entregas puede influir en la planeación.'],['Color y apariencia','Comparte RAL, muestra o especificación, junto con brillo y textura. Si no lo sabes, describe el uso y solicita orientación sin inventar un código.'],['Zonas protegidas','Marca roscas, contactos, alojamientos, superficies de ensamble y cualquier zona que no deba recibir recubrimiento. Un plano ayuda cuando existen tolerancias.'],['Entrega y uso','Indica fecha deseada, uso interior o exterior y condiciones relevantes. Tuled revisará disponibilidad y confirmará el alcance antes de programar.']],quote:'Fotografías, medidas y cantidad son el mejor punto de partida.',cta:'Enviar solicitud a Tuled',message:'Hola Tuled, quiero preparar una solicitud de cotización de pintura electrostática.',related:[2,1,4]},
  {id:7,slug:'proceso-aplicacion-pintura-electrostatica',title:'¿Cómo se aplica la pintura electrostática paso a paso?',cat:'Fundamentos',image:'articulo-7.webp',excerpt:'Del ingreso de las piezas a la preparación, aplicación, curado, inspección y entrega.',intro:'El proceso industrial es una cadena: una decisión en preparación o sujeción puede afectar aplicación, curado y acabado. Las etapas exactas cambian según sustrato y especificación, pero este recorrido permite entender qué se revisa.',points:[['Recepción y evaluación','Se identifica material, condición, dimensiones, cantidad, acabado y áreas protegidas. Las diferencias respecto de la muestra o plano deben aclararse antes de procesar.'],['Preparación de la superficie','Se eliminan contaminantes y se aplica el tratamiento compatible cuando corresponde. La ruta depende del metal, del estado de la pieza y del desempeño solicitado.'],['Colgado y puesta a tierra','La sujeción debe resistir manipulación y horno, permitir acceso y ofrecer continuidad eléctrica. El punto de contacto puede dejar una pequeña marca que conviene planear.'],['Aplicación en cabina','La pistola carga el polvo y el operador controla flujo, distancia y orientación. Bordes, cavidades y zonas tipo jaula de Faraday requieren atención.'],['Curado y enfriamiento','El ciclo se relaciona con la temperatura alcanzada por el metal y el tiempo indicado por el fabricante. Después, la pieza debe enfriarse antes de una manipulación segura.'],['Inspección y entrega','Se revisan apariencia y requisitos acordados. La protección, empaque y transporte deben evitar golpes o fricción sobre piezas terminadas.']],quote:'La calidad del acabado depende de una secuencia completa, no de una sola operación.',cta:'Cotizar un proceso de pintura',message:'Hola Tuled, leí el proceso paso a paso y quiero cotizar un lote de piezas.',related:[3,10,12]},
  {id:8,slug:'pintura-electrostatica-vs-pintura-liquida',title:'Pintura electrostática frente a pintura líquida: diferencias, ventajas y limitaciones',cat:'Fundamentos',image:'articulo-8.webp',excerpt:'Una comparación equilibrada para elegir el sistema según sustrato, acabado, volumen y uso.',intro:'Pintura en polvo y pintura líquida pueden producir acabados industriales valiosos. La elección correcta depende de sustrato, tamaño, temperatura admisible, reparación, volumen, color, desempeño y equipo disponible; no existe una respuesta universal.',points:[['Aplicación','El polvo suele depositarse electrostáticamente como material seco. La líquida utiliza un vehículo que se evapora o reacciona, según su tecnología. Ambas requieren control de aplicación y seguridad.'],['Curado o secado','Muchos polvos termoestables necesitan horno. Las pinturas líquidas pueden secar al aire o curar por distintos mecanismos; esto amplía opciones para piezas sensibles o muy grandes.'],['Materiales y geometría','El polvo favorece piezas que toleran calor y pueden aterrizarse. La líquida puede adaptarse a otros sustratos, reparaciones o ensambles, dependiendo del producto.'],['Apariencia y espesor','Ambos sistemas ofrecen colores y efectos. Películas muy delgadas, igualaciones específicas o retoques pueden resolverse de forma distinta; conviene validar muestras.'],['Material y ambiente','El polvo no utiliza un solvente portador durante aplicación, pero requiere manejo de partículas, extracción y protección. La pintura líquida exige controles acordes con sus solventes o componentes.'],['Decisión del proyecto','Compara desempeño, capacidad dimensional, preparación, energía, cambios de color, volumen y mantenimiento futuro. La ficha técnica y el uso final deben guiar la selección.']],quote:'El mejor sistema es el que responde a los requisitos reales de la pieza.',cta:'Consultar opciones de recubrimiento',message:'Hola Tuled, vi la comparación entre pintura en polvo y líquida y quiero revisar opciones para mi proyecto.',related:[3,9,10]},
  {id:9,slug:'epoxico-poliester-poliuretano-diferencias',title:'Epóxico, poliéster y poliuretano: diferencias entre recubrimientos industriales',cat:'Fundamentos',image:'articulo-9.webp',excerpt:'Cómo cambian las familias de recubrimiento según exposición, apariencia y requisitos técnicos.',intro:'Las familias químicas no son intercambiables por nombre. Dentro de cada una existen formulaciones diferentes, por lo que la ficha técnica del producto específico y las condiciones de servicio son indispensables para decidir.',points:[['Epóxicos','Suelen valorarse por adherencia y resistencia química en aplicaciones apropiadas. La exposición prolongada a radiación solar puede afectar apariencia en muchas formulaciones, por lo que debe revisarse su uso exterior.'],['Poliésteres','Existen formulaciones orientadas a aplicaciones exteriores y una amplia variedad de colores y acabados. El desempeño concreto depende del producto, preparación y ciclo de curado.'],['Poliuretanos','Pueden ofrecer opciones de apariencia y desempeño específicas. Disponibilidad, condiciones de aplicación, exposición y ficha técnica deben confirmarse para cada proyecto.'],['Exposición ambiental','Interior, exterior, radiación UV, humedad, productos químicos y temperatura de servicio cambian la decisión. Ninguna etiqueta genérica reemplaza los requisitos del entorno.'],['Apariencia','Brillo, textura, nivelación, color y retención estética varían con formulación y aplicación. Una muestra aprobada ayuda cuando la apariencia es crítica.'],['Selección informada','Define sustrato, preparación, ambiente, uso, pruebas y restricciones. Después compara fichas del fabricante y confirma compatibilidad con el proceso disponible.']],quote:'La familia química orienta la selección; la ficha técnica confirma el producto.',cta:'Consultar el acabado adecuado',message:'Hola Tuled, leí la comparación de epóxico, poliéster y poliuretano y quiero consultar el acabado adecuado.',related:[11,16,3]},
  {id:10,slug:'preparacion-metal-pintura-electrostatica',title:'¿Por qué es importante preparar el metal antes de aplicar pintura electrostática?',cat:'Fundamentos',image:'articulo-10.webp',excerpt:'Limpieza, desengrase, oxidación y tratamientos que condicionan la adherencia del acabado.',intro:'El recubrimiento no corrige por sí solo una superficie contaminada. Aceite, polvo, sales, oxidación y residuos pueden interferir con la adherencia o aparecer bajo el acabado. Por eso la preparación se define antes de aplicar pintura.',points:[['Contaminantes de fabricación','Aceites de corte, grasas, polvo y residuos de soldadura pueden permanecer aunque la pieza parezca limpia. Deben identificarse y retirarse mediante un proceso compatible.'],['Oxidación y recubrimientos anteriores','Óxido, cascarilla o pintura vieja requieren evaluación. Cubrirlos sin una ruta adecuada puede ocultar temporalmente un problema sin resolver la interfaz.'],['Limpieza y desengrase','Producto, concentración, tiempo, temperatura, enjuague y secado deben controlarse de acuerdo con el proceso. No existe un limpiador universal para todos los metales y suciedades.'],['Tratamientos de conversión','Fosfatizado u otros tratamientos pueden utilizarse cuando corresponda al sustrato y desempeño. Su selección debe considerar especificación, química y mantenimiento del baño.'],['Acero frente a aluminio','La química superficial y los óxidos naturales difieren. Un tratamiento apropiado para acero al carbón no debe asumirse automáticamente para aluminio.'],['Piezas usadas','Grasa absorbida, silicón, corrosión, reparación previa o contaminación de servicio pueden requerir pruebas. Fotografías y antecedentes ayudan a decidir si la pieza es recuperable.']],quote:'El acabado comienza antes de aplicar la pintura.',cta:'Evaluar la preparación de mis piezas',message:'Hola Tuled, leí el artículo sobre preparación del metal y quiero evaluar unas piezas antes de pintarlas.',related:[7,16,12]},
  {id:11,slug:'acabados-mate-brillante-texturizado',title:'Acabados mate, brillantes, lisos y texturizados: ¿cómo elegir el adecuado?',cat:'Fundamentos',image:'articulo-11.webp',excerpt:'Diferencias de apariencia, limpieza y uso entre brillos y texturas industriales.',intro:'El acabado comunica calidad visual, pero también afecta cómo se perciben marcas, ondulaciones, limpieza y color. Elegirlo requiere observar una muestra real y relacionarla con la pieza y su entorno.',points:[['Mate y semibrillante','Un mate reduce reflejos y puede ofrecer una apariencia sobria. El semibrillante equilibra reflejo y lectura de superficie; el nivel exacto depende del producto y medición acordada.'],['Brillante','Resalta color y reflejo, pero también puede hacer más visibles ciertas ondulaciones o defectos del sustrato. La preparación y la uniformidad adquieren importancia.'],['Liso','Un acabado liso facilita apreciar nivelación y color. No elimina soldaduras, golpes o marcas de fabricación presentes en el metal.'],['Texturizado','La textura aporta una apariencia táctil y puede disimular pequeñas variaciones visuales. No debe usarse para ocultar defectos estructurales o contaminación.'],['Limpieza y servicio','Relieve, brillo, color y exposición influyen en la limpieza. Para requisitos de higiene o mantenimiento se debe validar el producto y el método de limpieza.'],['Aprobación de muestra','RAL, fotografía o pantalla no garantizan una coincidencia visual exacta. Cuando el color es crítico conviene aprobar una placa o pieza representativa.']],quote:'Color, brillo y textura deben evaluarse juntos sobre una muestra real.',cta:'Consultar colores y acabados',message:'Hola Tuled, vi la guía de acabados mate, brillantes y texturizados y quiero consultar opciones.',related:[9,14,15]},
  {id:12,slug:'horno-curado-pintura-electrostatica',title:'¿Cómo funciona el horno de curado de la pintura electrostática?',cat:'Fundamentos',image:'articulo-12.webp',excerpt:'Temperatura del metal, tiempo, masa térmica, enfriamiento y validación del ciclo.',intro:'Después de aplicar el polvo, el recubrimiento necesita alcanzar las condiciones de curado definidas por su fabricante. El horno aporta energía, pero lo importante es lo que sucede en la pieza y en la película durante el tiempo requerido.',points:[['Flujo y reacción','Al calentarse, el polvo se funde, fluye y, en sistemas termoestables, reacciona para formar una película. El ciclo depende de la formulación específica.'],['Aire del horno y metal','La temperatura indicada por el equipo no equivale automáticamente a la temperatura de la pieza. El metal tarda en calentarse según masa, geometría, carga y circulación de aire.'],['Masa y espesor','Una placa gruesa suele necesitar más tiempo para alcanzar temperatura que una lámina delgada. Mezclar masas muy diferentes en una carga exige planeación.'],['Curado insuficiente','Si no se alcanzan tiempo y temperatura de metal, la película puede no desarrollar las propiedades previstas. La apariencia por sí sola no siempre confirma el curado.'],['Exceso de ciclo','Exceder condiciones recomendadas puede afectar color, brillo o desempeño según la formulación. No debe asumirse que más tiempo siempre mejora el resultado.'],['Enfriamiento y verificación','Las piezas deben enfriarse antes de empacar o manipular. Los métodos de verificación se acuerdan según el proyecto, ficha técnica y requisitos del cliente.']],quote:'El horno calienta el aire; el proceso se valida sobre la respuesta térmica de la pieza.',cta:'Cotizar un proyecto de recubrimiento',message:'Hola Tuled, leí el artículo sobre curado y quiero cotizar un proyecto de recubrimiento.',related:[7,3,10]},
  {id:13,slug:'recubrimientos-climatizacion-refrigeracion',title:'Recubrimientos industriales para piezas de climatización y refrigeración',cat:'Aplicaciones',image:'articulo-13.webp',excerpt:'Consideraciones de fabricantes para cubiertas, rejillas, soportes y lotes de producción HVAC.',intro:'Fabricantes de climatización y refrigeración requieren combinar apariencia, repetibilidad y compatibilidad con ensamble. Cubiertas, rejillas y soportes pueden compartir color, pero sus geometrías y puntos críticos no son iguales.',points:[['Gabinetes y cubiertas','Puertas, paneles y envolventes requieren atención a bordes, uniones, áreas visibles y puntos de montaje. La referencia de color debe formar parte del control del lote.'],['Rejillas y perforados','Las perforaciones multiplican bordes y zonas de acceso. La orientación durante la aplicación y el colgado influye en cobertura y marcas de contacto.'],['Soportes y bases','Componentes soldados pueden presentar salpicadura, rebabas o aceites. Conviene definir qué preparación llega hecha y qué debe realizar el aplicador.'],['Exterior y apariencia','Exposición solar, humedad, agentes de limpieza y requisitos de apariencia orientan la selección. La formulación se confirma con fichas y especificaciones aplicables.'],['Producción por lotes','Familias, cantidades, empaque, lotificación y entregas parciales deben acordarse. Una pieza patrón y criterios visuales ayudan a alinear expectativas.'],['Datos de cotización','Incluye planos, masa, material, volumen, color, acabado, exposición, zonas enmascaradas, calendario y pruebas o documentos solicitados.']],quote:'La repetibilidad empieza con especificaciones claras y una pieza bien definida.',cta:'Cotizar componentes de climatización',message:'Hola Tuled, leí el artículo para fabricantes de climatización y quiero cotizar componentes.',related:[5,18,14]},
  {id:14,slug:'pintura-electrostatica-gabinetes-electricos',title:'Pintura electrostática para gabinetes eléctricos y tableros de control',cat:'Aplicaciones',image:'articulo-14.webp',excerpt:'Preparación, perforaciones, enmascarado y apariencia de envolventes y paneles metálicos.',intro:'En un gabinete, el acabado debe convivir con puertas, tapas, herrajes, empaques, roscas y puntos de contacto. La pintura aporta acabado superficial, pero no sustituye el diseño eléctrico ni garantiza por sí misma seguridad, continuidad o clasificación ambiental.',points:[['Envolventes, puertas y tapas','Las superficies visibles requieren uniformidad y cuidado en bordes. Bisagras, cierres, empaques y tolerancias deben considerarse antes del recubrimiento.'],['Preparación de lámina','Aceite de punzonado, marcas, soldadura y oxidación afectan el resultado. La condición de fabricación debe comunicarse y mantenerse consistente entre lotes.'],['Perforaciones y bordes','Ventanas, knockouts y perforaciones crean cantos y zonas de acceso. Es importante revisar rebabas y definir qué caras se recubren.'],['Enmascarado funcional','Roscas, pernos de tierra, contactos, alojamientos y superficies de ensamble pueden necesitar protección. El cliente debe identificar requisitos eléctricos y mecánicos.'],['Color y ambiente','Color, brillo, textura e interior o exterior orientan la formulación. Una especificación del gabinete debe prevalecer sobre preferencias generales.'],['Cotización de fabricación','Comparte planos, variantes, cantidades, peso, áreas libres, estándar de apariencia, empaque y calendario. No se debe alterar el diseño de puesta a tierra sin autorización técnica.']],quote:'El recubrimiento debe integrarse al diseño del gabinete, no modificarlo por accidente.',cta:'Cotizar gabinetes metálicos',message:'Hola Tuled, vi su artículo sobre gabinetes eléctricos y deseo solicitar una cotización.',related:[1,11,18]},
  {id:15,slug:'pintura-electrostatica-racks-estructuras',title:'Pintura electrostática para racks, estanterías y estructuras metálicas',cat:'Aplicaciones',image:'articulo-15.webp',excerpt:'Planeación de postes, travesaños, repisas y bastidores por lote.',intro:'Racks y estructuras combinan piezas largas, uniones, perfiles abiertos o cerrados y superficies de contacto. Para recubrirlas de forma ordenada se deben planear preparación, colgado, manipulación, color, lote y transporte.',points:[['Componentes típicos','Postes, travesaños, repisas, marcos y bastidores pueden separarse por familia. Cada geometría requiere puntos de sujeción y orientación propios.'],['Preparación del acero','Aceite, oxidación, salpicadura de soldadura y rebabas deben tratarse según el alcance. Pintar sobre contaminantes compromete la interfaz.'],['Color y acabado','El color puede apoyar identificación o imagen del equipo. Brillo y textura deben definirse con muestra cuando la apariencia de grandes superficies sea importante.'],['Volumen y lotificación','Cantidades por modelo, frecuencia, mezcla de colores y entregas parciales influyen en la programación. Etiquetado y racks de transporte evitan confusiones.'],['Manipulación y traslado','Las piezas largas pueden golpearse o rozar después del acabado. Separadores, empaque y método de carga forman parte de la calidad entregada.'],['Cotizar por lote','Envía plano o fotos, medidas, peso, material, cantidad por tipo, color, uso y calendario. Aclara si las estructuras llegan desarmadas.']],quote:'La geometría influye tanto en la aplicación como en la forma de mover la pieza.',cta:'Cotizar pintura para estructuras',message:'Hola Tuled, leí el artículo sobre racks y estructuras y quiero cotizar pintura para un lote.',related:[1,11,17]},
  {id:16,slug:'pintura-electrostatica-aluminio',title:'Pintura electrostática en aluminio: preparación, aplicaciones y acabados',cat:'Aplicaciones',image:'articulo-16.webp',excerpt:'Qué revisar en perfiles, marcos, láminas y cubiertas de aluminio.',intro:'El aluminio puede recibir pintura en polvo, pero su química superficial y aleación requieren una preparación compatible. No debe tratarse como si fuera acero al carbón: limpieza, conversión, adherencia y ciclo térmico se evalúan para la pieza concreta.',points:[['Óxido natural y limpieza','El aluminio forma una capa superficial propia y puede contener lubricantes de extrusión o fabricación. La limpieza debe retirar contaminantes sin dañar el sustrato.'],['Perfiles y marcos','Perfiles extruidos, marcos y componentes huecos pueden retener líquidos o aire y presentar zonas profundas. Drenaje, colgado y contacto eléctrico se planean.'],['Láminas y cubiertas','Las láminas pueden deformarse o mostrar ondulaciones. Manipulación, espesor, perforaciones y superficies visibles deben revisarse antes.'],['Pretratamiento compatible','La ruta química debe corresponder a la aleación, uso y especificación. No se debe trasladar automáticamente una preparación de acero al aluminio.'],['Interior y exterior','La exposición orienta la familia de recubrimiento y el nivel de preparación. Para exterior se revisan ficha técnica, color y requisitos de durabilidad.'],['Datos para cotizar','Indica aleación si se conoce, dimensiones, masa, cantidad, condición, acabado, exposición y zonas sin pintura. Una muestra puede ayudar a validar apariencia.']],quote:'No todos los metales se preparan de la misma manera.',cta:'Cotizar piezas de aluminio',message:'Hola Tuled, encontré el artículo sobre pintura electrostática en aluminio y quiero cotizar unas piezas.',related:[10,9,1]},
  {id:17,slug:'recubrimientos-soportes-automotrices',title:'Recubrimientos para soportes y componentes de la industria automotriz',cat:'Aplicaciones',image:'articulo-17.webp',excerpt:'Soportes, bases, escuadras y componentes soldados sujetos a requisitos del cliente.',intro:'Soportes y componentes para fabricación automotriz pueden evaluarse para pintura en polvo cuando sus requisitos están claramente definidos. La pertenencia a una aplicación automotriz no implica que cualquier proceso cumpla automáticamente una especificación del fabricante.',points:[['Tipos de componente','Soportes, bases, escuadras, placas y ensambles soldados son candidatos posibles. Material, masa, geometría y función deben identificarse.'],['Geometría y soldadura','Cavidades, dobleces, cordones y traslapes influyen en limpieza, sujeción y cobertura. Rebabas o salpicaduras deben controlarse antes.'],['Áreas libres y tolerancias','Roscas, caras de ensamble, contactos y diámetros funcionales pueden requerir enmascarado. El espesor del recubrimiento debe considerarse en tolerancias.'],['Especificación del cliente','Color, formulación, preparación, pruebas, documentación y criterios de aceptación deben provenir de requisitos vigentes, no de supuestos.'],['Producción por lotes','Identificación, trazabilidad acordada, pieza patrón, empaque y variaciones de fabricación ayudan a mantener consistencia. Cada proyecto define su nivel documental.'],['Alcance de Tuled','La capacidad se revisa contra el componente y la especificación. Este contenido no afirma acreditaciones automotrices ni aprobación automática por fabricantes de vehículos.']],quote:'En componentes industriales, la especificación del cliente define el objetivo.',cta:'Cotizar componentes metálicos',message:'Hola Tuled, vi su artículo sobre soportes automotrices y deseo cotizar componentes metálicos.',related:[1,15,14]},
  {id:18,slug:'pintura-electrostatica-laminas-perforadas',title:'Pintura electrostática para láminas perforadas y piezas de geometría compleja',cat:'Aplicaciones',image:'articulo-18.webp',excerpt:'Cómo influyen perforaciones, bordes, pliegues y cavidades en la aplicación del polvo.',intro:'Una pieza de geometría compleja combina zonas abiertas con rincones, cavidades, dobleces o múltiples bordes. La nube de polvo no se deposita igual en todas ellas; la orientación, puesta a tierra y técnica deben adaptarse.',points:[['Lámina perforada y rejillas','Paneles de ventilación, guardas y rejillas multiplican cantos. El tamaño, patrón, espesor y relación de área abierta influyen en el acceso y apariencia.'],['Pliegues y cavidades','Canales, esquinas internas y cavidades pueden presentar efecto de jaula de Faraday. Ajustes de aplicación y orientación ayudan, pero cada diseño tiene límites.'],['Sujeción y contacto','La pieza debe sostenerse sin deformarse y mantener contacto eléctrico. El punto de colgado deja una zona que conviene ubicar fuera de la cara crítica.'],['Cobertura en bordes','Los bordes se comportan distinto a las superficies planas. Preparación, espesor, formulación y aplicación influyen en la continuidad del acabado.'],['Inspección','Conviene definir caras visibles, nivel aceptable en cavidades y zonas funcionales. Una expectativa uniforme sin considerar geometría puede ser poco realista.'],['Fotos y planos','Incluye vistas de frente, reverso, perfil, pliegues y cavidades, además de medidas, material, cantidad y zonas críticas. Un plano evita interpretar mal la forma.']],quote:'La forma de la pieza también influye en cómo se aplica el recubrimiento.',cta:'Cotizar piezas de geometría especial',message:'Hola Tuled, leí el artículo sobre láminas perforadas y quiero cotizar piezas de geometría especial.',related:[1,5,13]},
  {id:19,slug:'medicion-espesor-pintura-electrostatica',title:'¿Cómo se mide el espesor de la pintura electrostática?',cat:'Fundamentos',image:'articulo-19.webp',excerpt:'Qué significa el espesor de película y cómo se revisa con instrumentos sobre una pieza terminada.',intro:'El espesor es una variable importante del acabado, pero una sola lectura no describe toda una pieza. El tipo de metal, el instrumento, la calibración, la geometría y los puntos de medición deben definirse para obtener resultados comparables.',points:[['Qué se está midiendo','La medición busca conocer el espesor de la película seca sobre el sustrato. El resultado suele expresarse en micras o milésimas de pulgada según la especificación.'],['Instrumento adecuado','El medidor debe ser compatible con el sustrato. No se utiliza necesariamente el mismo principio para acero que para aluminio u otros metales no ferrosos.'],['Calibración y verificación','Antes de medir conviene verificar el equipo con patrones apropiados y considerar la superficie base. La rugosidad del metal puede influir en la lectura.'],['Dónde medir','Bordes, curvas, cavidades y superficies planas pueden mostrar valores distintos. Un plan de puntos evita elegir solamente las zonas más favorables.'],['Interpretación de lecturas','Se revisan varias lecturas y se comparan con el criterio acordado. Una lectura aislada no debe sustituir la evaluación del conjunto ni otros requisitos de apariencia.'],['Información para el proyecto','Si el espesor es crítico, comparte el rango, método, zonas y criterio de aceptación desde la cotización. Tuled puede revisar el alcance para proyectos en Monterrey y su área metropolitana.']],quote:'Medir bien requiere instrumento, método y puntos definidos.',cta:'Consultar requisitos de espesor',message:'Hola Tuled, leí el artículo sobre medición de espesor y quiero revisar los requisitos de mi proyecto.',related:[7,10,23]},
  {id:20,slug:'defectos-acabado-pintura-electrostatica',title:'Defectos comunes en pintura electrostática: textura, cráteres y piel de naranja',cat:'Fundamentos',image:'articulo-20.webp',excerpt:'Cómo reconocer variaciones de apariencia y qué variables conviene revisar antes de corregirlas.',intro:'Una variación visual puede tener distintas causas. Contaminación, preparación, aplicación, espesor, formulación o ciclo térmico pueden producir síntomas parecidos, por lo que conviene revisar el proceso completo antes de atribuir el problema a una sola etapa.',points:[['Piel de naranja','Una textura ondulada puede relacionarse con formulación, espesor, aplicación o condiciones de flujo y curado. El nivel aceptable depende de la muestra y del uso de la pieza.'],['Cráteres y ojos de pescado','Pequeñas depresiones pueden indicar contaminación o incompatibilidad. Silicones, aceites, humedad y residuos deben investigarse en pieza, ambiente y equipo.'],['Burbujas y poros','El aire o los gases atrapados pueden aparecer durante el calentamiento, especialmente en ciertos sustratos, fundiciones o superficies contaminadas.'],['Cobertura irregular','Sombras en cavidades, exceso en bordes o diferencias de espesor pueden relacionarse con geometría, puesta a tierra, flujo, distancia y orientación.'],['Diferencias de color o brillo','Lote, espesor, temperatura y tiempo pueden influir en apariencia. Una muestra aprobada ayuda a comparar con un criterio real y no solo con una pantalla.'],['Cómo analizar una falla','Registra pieza, lote, polvo, preparación, parámetros, horno y ubicación del defecto. La evidencia permite separar una causa repetitiva de un evento aislado.']],quote:'El defecto visible es una pista; el diagnóstico necesita revisar todo el proceso.',cta:'Revisar un problema de acabado',message:'Hola Tuled, leí el artículo sobre defectos de acabado y quiero revisar un problema en mis piezas.',related:[10,12,19]},
  {id:21,slug:'pintura-electrostatica-estructuras-grandes-monterrey',title:'Pintura electrostática para estructuras metálicas grandes en Monterrey',cat:'Aplicaciones',image:'articulo-21.webp',excerpt:'Qué considerar al cotizar vigas, perfiles y componentes de gran longitud para recubrimiento en polvo.',intro:'Las piezas largas requieren más que espacio físico: deben poder prepararse, manipularse, colgarse, aterrizarse, calentarse y transportarse con seguridad. Tuled puede evaluar vigas de hasta 6 metros, sujeto a geometría, peso, condición y requisitos del proyecto.',points:[['Dimensiones completas','Comparte largo, ancho, alto, peso y fotografías. La longitud por sí sola no confirma viabilidad porque salientes, placas y ensambles cambian el volumen efectivo.'],['Vigas de hasta 6 metros','En Tuled contamos con experiencia para evaluar vigas y perfiles de hasta 6 metros. La aceptación final depende de la revisión de cada familia de piezas y de su manejo.'],['Preparación de superficie','Óxido, aceite, cascarilla, soldadura y recubrimientos anteriores determinan la ruta necesaria. Las caras cerradas o traslapadas merecen atención especial.'],['Colgado y manipulación','Los puntos de sujeción deben soportar la pieza y mantener continuidad eléctrica. También se planean giros, transferencia y enfriamiento sin dañar el acabado.'],['Curado de piezas grandes','La masa del metal influye en el tiempo para alcanzar temperatura. El ciclo debe considerar la respuesta térmica de la pieza y la ficha del recubrimiento.'],['Logística en Monterrey','Desde Apodaca atendemos proyectos de Monterrey y Nuevo León. Conviene acordar transporte, protección entre piezas, carga y descarga desde la cotización.']],quote:'Una pieza grande se evalúa como un proceso completo, no solamente por su longitud.',cta:'Cotizar vigas o estructuras grandes',message:'Hola Tuled, estoy en Monterrey y quiero cotizar vigas o estructuras metálicas de gran longitud.',related:[15,7,24]},
  {id:22,slug:'limpieza-mantenimiento-piezas-pintura-electrostatica',title:'¿Cómo limpiar y mantener piezas con pintura electrostática?',cat:'Fundamentos',image:'articulo-22.webp',excerpt:'Recomendaciones generales para conservar la apariencia sin dañar innecesariamente el recubrimiento.',intro:'El mantenimiento depende del ambiente, la formulación y el uso. Una limpieza suave y frecuente suele ser preferible a dejar que la contaminación se acumule y después recurrir a productos agresivos o herramientas abrasivas.',points:[['Comienza por lo más suave','Retira polvo suelto y utiliza agua con un limpiador neutro cuando sea compatible. Prueba primero en una zona poco visible.'],['Evita abrasivos innecesarios','Fibras duras, lijas y polvos abrasivos pueden rayar o cambiar el brillo. Un paño suave ayuda a reducir marcas durante la limpieza.'],['Cuidado con químicos','Solventes, desengrasantes concentrados y limpiadores alcalinos o ácidos pueden afectar algunos recubrimientos. Consulta la ficha o realiza una prueba controlada.'],['Enjuague y secado','Los residuos de detergente pueden dejar manchas o atraer suciedad. Enjuaga y seca para evitar acumulación en uniones, bordes o zonas horizontales.'],['Inspección periódica','Revisa golpes, rayas, corrosión en bordes y zonas de contacto. Detectar daño temprano facilita definir una acción antes de que avance.'],['Plan según el ambiente','Exterior, salpicaduras químicas, grasa industrial o alta manipulación requieren frecuencias distintas. El responsable del equipo debe establecer el plan según su exposición.']],quote:'Conservar el acabado comienza con una limpieza compatible y sin abrasión excesiva.',cta:'Consultar el acabado para tu aplicación',message:'Hola Tuled, leí la guía de limpieza y quiero consultar el acabado adecuado para mis piezas.',related:[9,11,16]},
  {id:23,slug:'inspeccion-calidad-pintura-electrostatica',title:'Control de calidad en pintura electrostática: qué se revisa antes de entregar',cat:'Fundamentos',image:'articulo-23.webp',excerpt:'Apariencia, cobertura, espesor, curado y criterios acordados para evaluar un lote terminado.',intro:'La inspección debe responder a requisitos conocidos. Apariencia, espesor, color, zonas libres y documentación no se evalúan igual en todos los proyectos; por eso los criterios deben acordarse antes de producir el lote.',points:[['Identificación y trazabilidad','Se confirma la familia de pieza, cantidad, color y alcance. Cuando el proyecto lo requiere, lote y registros ayudan a relacionar el resultado con el proceso.'],['Apariencia general','Se revisan áreas visibles, uniformidad, contaminación, marcas y daños de manejo bajo condiciones razonables de observación. La muestra aprobada orienta la comparación.'],['Cobertura y zonas críticas','Cavidades, bordes, perforaciones y reversos se observan según el nivel acordado. También se verifican áreas enmascaradas y superficies funcionales.'],['Espesor y curado','Cuando aplica, las mediciones y verificaciones se realizan con métodos y criterios definidos. La apariencia por sí sola no sustituye un requisito técnico.'],['Empaque y liberación','Una pieza aceptada todavía puede dañarse por fricción, apilado o transporte. Separadores y protección deben corresponder a la geometría y acabado.'],['Compromiso de calidad','Tuled trabaja con un sistema de gestión certificado ISO 9001:2015. El alcance específico, documentos y requisitos del proyecto se confirman directamente con nuestro equipo.']],quote:'La calidad se vuelve verificable cuando el criterio está definido antes de inspeccionar.',cta:'Consultar un proyecto con requisitos de calidad',message:'Hola Tuled, leí el artículo sobre control de calidad y quiero revisar los requisitos de mi proyecto.',related:[19,7,10]},
  {id:24,slug:'planeacion-lotes-pintura-electrostatica-monterrey',title:'Cómo planear lotes de pintura electrostática para producción industrial en Monterrey',cat:'Cotización',image:'articulo-24.webp',excerpt:'Datos, familias de piezas y logística para organizar pedidos recurrentes o de mayor volumen.',intro:'Un lote bien planeado reduce dudas, mezclas de referencias y movimientos innecesarios. La información sobre familias, cantidades, colores, calendario y empaque permite revisar capacidad y proponer una secuencia más clara.',points:[['Agrupa por familia','Separa piezas por modelo, medidas, material y acabado. Una lista con claves evita tratar como iguales componentes que requieren manejo distinto.'],['Define cantidades y frecuencia','Indica volumen total, piezas por entrega y repetición esperada. Esto ayuda a distinguir una necesidad única de un programa recurrente.'],['Consolida colores y acabados','Agrupar referencias compatibles puede simplificar la planeación. Cambios de color, texturas o formulaciones deben identificarse desde el inicio.'],['Planos, muestras y revisiones','Comparte planos vigentes, zonas protegidas y criterios de apariencia. Controla los cambios para que producción y cotización trabajen con la misma versión.'],['Empaque y transporte','Define separadores, racks, protección y responsable de traslado. La logística debe evitar roces y golpes después de liberar el acabado.'],['Atención industrial en Monterrey','Tuled se ubica en Apodaca y atiende empresas de Monterrey y su zona metropolitana. Para programar, confirma disponibilidad, alcance y fechas con nuestro equipo.']],quote:'Un lote ordenado empieza con referencias, cantidades y fechas que todos pueden identificar.',cta:'Planear un lote de producción',message:'Hola Tuled, estoy en Monterrey y quiero planear un lote de piezas para pintura electrostática.',related:[6,15,21]}
];

