const card = (a,prefix='') => `<article class="blog-card reveal" data-article-card data-category="${esc(a.cat)}" data-search="${esc(`${a.title} ${a.excerpt} ${a.cat}`.toLowerCase())}"><a class="blog-card-media" href="${prefix}blog/${a.slug}.html"><img src="${prefix}imgs/${a.image}" alt="Portada: ${esc(a.title)}" loading="lazy"><span>${String(a.id).padStart(2,'0')}</span></a><div class="blog-card-copy"><span class="kicker">${esc(a.cat)}</span><h2><a href="${prefix}blog/${a.slug}.html">${esc(a.title)}</a></h2><p>${esc(a.excerpt)}</p><a class="blog-read" href="${prefix}blog/${a.slug}.html">Leer artículo <span aria-hidden="true">→</span></a></div></article>`;

const indexHtml = `<!doctype html><html lang="es-MX"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">${identityHead}<title>Blog de pintura electrostática industrial | Tuled</title><meta name="description" content="Guías sobre pintura electrostática, cotización, preparación, acabados y aplicaciones industriales para empresas de Monterrey y Nuevo León.">${socialHead('Biblioteca de pintura electrostática | Tuled','Guías técnicas para comprender y cotizar acabados industriales.',`${domain}/blog.html`)}<link rel="stylesheet" href="styles.css?v=20261030-v3-25"><link rel="stylesheet" href="blog.css?v=20261030-v3-25"><script src="script.js?v=20261030-v3-25" defer></script><script src="blog.js?v=20261030-v3-25" defer></script></head><body class="with-video-bg blog-index">${video}${header('')}<main id="contenido"><section class="blog-landing"><div class="container blog-landing-inner"><span class="kicker">Blog Tuled</span><h1>Nuestro blog. <span class="title-accent">Aprende aquí.</span></h1><p>Si tienes dudas sobre pintura electrostática, materiales o acabados, aquí encontrarás explicaciones claras para orientar tu proyecto.</p></div></section><section class="section blog-library"><div class="container"><div class="blog-tools glass-panel"><label class="blog-search"><span>Buscar en el blog</span><input type="search" data-blog-search placeholder="Ej. aluminio, gabinetes, cotización…"></label><div class="blog-filters" aria-label="Filtrar artículos"><button class="is-active" type="button" data-blog-filter="Todos">Todos</button><button type="button" data-blog-filter="Fundamentos">Fundamentos</button><button type="button" data-blog-filter="Cotización">Cotización</button><button type="button" data-blog-filter="Aplicaciones">Aplicaciones</button></div></div><p class="blog-results" data-blog-results>Explora nuestras guías técnicas</p><div class="blog-grid">${articles.map(a=>card(a)).join('')}</div><div class="blog-empty" data-blog-empty hidden><strong>No encontramos coincidencias.</strong><span>Prueba otra palabra o selecciona “Todos”.</span></div></div></section><section class="section blog-local"><div class="container glass-panel"><span class="kicker">Tuled · Apodaca, Nuevo León</span><h2>Información técnica cercana a la industria de Monterrey.</h2><p>Desde nuestras instalaciones en Apodaca atendemos solicitudes de pintura electrostática para piezas metálicas de empresas de Monterrey y su área metropolitana.</p><a class="btn btn-primary" href="index.html#contacto">Hablemos de tu proyecto</a></div></section></main>${footer('')}</body></html>`;
