  return `<div class="article-media-strip"><img src="../imgs/evidencia-3.webp" alt="Piezas metálicas en instalaciones de Tuled" loading="lazy"><img src="../imgs/evidencia-10.webp" alt="Proceso industrial de recubrimiento" loading="lazy"><img src="../imgs/evidencia-11.webp" alt="Equipo de Tuled trabajando" loading="lazy"></div>`;
